css_snippet:
body {
  /* Your primary web font */
  font-family: "Inter",
               /* System UI fonts for local fallback */
               -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen-Sans, Ubuntu, Cantarell,
               /* Generic sans-serif fallback */
               "Helvetica Neue", Arial, sans-serif;
  /* A consistent line-height helps prevent layout shifts if font metrics vary */
  line-height: 1.5;
}

h1 {
  font-family: "Playfair Display",
               /* A good system serif alternative */
               "Georgia",
               /* Generic serif fallback */
               serif;
  line-height: 1.2;
}
